#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_N 100001
#define MAX_M 200001

typedef struct Edge {
    int to;
    int t;
    int c;
    int next;
} Edge;

Edge edges[MAX_M];
int head[MAX_N];
int edge_cnt;

int dist[MAX_N]; // minimum wet time to reach each node
int heap[MAX_N];
int heap_pos[MAX_N];
int heap_size;

void init() {
    edge_cnt = 0;
    for (int i = 0; i < MAX_N; i++) {
        head[i] = -1;
        dist[i] = INT_MAX;
        heap_pos[i] = -1;
    }
}

void add_edge(int u, int v, int t, int c) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].t = t;
    edges[edge_cnt].c = c;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void swap(int i, int j) {
    int temp = heap[i];
    heap[i] = heap[j];
    heap[j] = temp;
    heap_pos[heap[i]] = i;
    heap_pos[heap[j]] = j;
}

void heapify_up(int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (dist[heap[idx]] < dist[heap[parent]]) {
            swap(idx, parent);
            idx = parent;
        } else {
            break;
        }
    }
}

void heapify_down(int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;

    if (left < heap_size && dist[heap[left]] < dist[heap[smallest]]) {
        smallest = left;
    }
    if (right < heap_size && dist[heap[right]] < dist[heap[smallest]]) {
        smallest = right;
    }

    if (smallest != idx) {
        swap(idx, smallest);
        heapify_down(smallest);
    }
}

void push(int node) {
    heap[heap_size] = node;
    heap_pos[node] = heap_size;
    heap_size++;
    heapify_up(heap_size - 1);
}

int pop() {
    int node = heap[0];
    heap_size--;
    heap[0] = heap[heap_size];
    heap_pos[heap[0]] = 0;
    heapify_down(0);
    heap_pos[node] = -1;
    return node;
}

int is_empty() {
    return heap_size == 0;
}

void dijkstra(int start) {
    dist[start] = 0;
    push(start);

    while (!is_empty()) {
        int u = pop();

        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            int t = edges[i].t;
            int c = edges[i].c;

            // wait time at u if we arrive before departure
            int wait = 0;
            if (dist[u] < t) {
                wait = t - dist[u];
            }

            int new_dist = dist[u] + wait + c;

            if (new_dist < dist[v]) {
                dist[v] = new_dist;
                if (heap_pos[v] == -1) {
                    push(v);
                } else {
                    heapify_up(heap_pos[v]);
                }
            }
        }
    }
}

