#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    int from, to;
    ll t, c;
} Edge;

typedef struct {
    ll key;
    int v;
} HeapNode;

typedef struct {
    HeapNode *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, ll key, int v) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].key > key) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].key = key;
    h->a[i].v = v;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->size--];
    int i = 1;
    while (i * 2 <= h->size) {
        int c = i * 2;
        if (c + 1 <= h->size && h->a[c + 1].key < h->a[c].key) c++;
        if (h->a[c].key >= last.key) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int cmp_edge_time_desc(const void *a, const void *b) {
    const Edge *x = (const Edge *)a;
    const Edge *y = (const Edge *)b;
    if (x->t < y->t) return 1;
    if (x->t > y->t) return -1;
    return 0;
}

int main(void) {
    int N, M, S, G;
    if (scanf("%d %d %d %d", &N, &M, &S, &G) != 4) return 0;
    S--; G--;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * M);
    for (int i = 0; i < M; i++) {
        int u, v;
        ll t, c;
        scanf("%d %d %lld %lld", &u, &v, &t, &c);
        u--; v--;
        edges[i].from = u;
        edges[i].to = v;
        edges[i].t = t;
        edges[i].c = c;
    }

    qsort(edges, M, sizeof(Edge), cmp_edge_time_desc);

    ll *best = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) best[i] = LLONG_MAX;
    best[G] = 0;

    MinHeap heap;
    heap_init(&heap, N + 4);
    heap_push(&heap, 0, G);

    int idx = 0;
    while (idx < M) {
        ll curT = edges[idx].t;

        while (heap.size > 0 && heap.a[1].key <= curT) {
            HeapNode nd = heap_pop(&heap);
            if (nd.key != best[nd.v]) continue;

            while (idx < M && edges[idx].t >= nd.key) {
                int u = edges[idx].from;
                int v = edges[idx].to;
                ll cand = nd.key + edges[idx].c;
                if (v == nd.v && cand < best[u]) {
                    best[u] = cand;
                    heap_push(&heap, cand, u);
                }
                idx++;
            }
        }

        if (heap.size == 0 || heap.a[1].key > curT) {
            idx++;
        }
    }

    if (best[S] == LLONG_MAX) {
        printf("-1\n");
    } else {
        printf("%lld\n", best[S]);
    }

    free(edges);
    free(best);
    free(heap.a);
    return 0;
}

