struct Edge {
    int to;
    ll depart, cost;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, S, G;
    cin >> N >> M >> S >> G;
    --S; --G;

    vector<vector<Edge>> g(N);
    for (int i = 0; i < M; i++) {
        int u, v;
        ll t, c;
        cin >> u >> v >> t >> c;
        --u; --v;
        g[u].push_back({v, t, c});
    }

    // dist[x] = minimum total wet time needed to be at stop x
    vector<ll> dist(N, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;

    dist[S] = 0;
    pq.push({0, S});

    while (!pq.empty()) {
        auto [curWet, u] = pq.top();
        pq.pop();
        if (curWet != dist[u]) continue;

        for (auto &e : g[u]) {
            // If current wet time is w, then:
            // - waiting until departure e.depart adds max(0, e.depart - w)
            // - riding adds e.cost
            // Total becomes max(w, e.depart) + e.cost
            ll nw = max(curWet, e.depart) + e.cost;
            if (nw < dist[e.to]) {
                dist[e.to] = nw;
                pq.push({nw, e.to});
            }
        }
    }

    if (dist[G] == INF) cout << -1 << '\n';
    else cout << dist[G] << '\n';

    return 0;
}

