public class Main {
    static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int S = Integer.parseInt(st.nextToken());
        int G = Integer.parseInt(st.nextToken());

        // Build adjacency list: for each stop, list of (nextStop, departureTime, travelDuration)
        List<Edge>[] graph = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            graph[u].add(new Edge(v, t, c));
        }

        // dist[i] = minimum total wet time to reach stop i
        long[] dist = new long[N + 1];
        Arrays.fill(dist, INF);
        dist[S] = 0;

        // Min-heap: (currentWetTime, stop)
        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(n -> n.wetTime));
        pq.offer(new Node(S, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            int u = cur.stop;
            long curWet = cur.wetTime;

            if (curWet != dist[u]) continue; // outdated entry

            for (Edge e : graph[u]) {
                // Wet time: waiting from arrival time (curWet) until departure time e.t, then travel e.c
                long wait = 0;
                if (curWet < e.t) {
                    wait = e.t - curWet;
                }
                // If we arrive after departure, we cannot take this bus (must wait for next, but no schedule given)
                // In this problem, we assume we can only take the bus if we arrive <= departure time.
                // If curWet > e.t, we miss this bus; we cannot take it. So skip.
                if (curWet > e.t) continue;

                long newWet = curWet + wait + e.c;
                if (newWet < dist[e.v]) {
                    dist[e.v] = newWet;
                    pq.offer(new Node(e.v, newWet));
                }
            }
        }

        System.out.println(dist[G]);
    }

    static class Edge {
        int v, t, c;
        Edge(int v, int t, int c) {
            this.v = v;
            this.t = t;
            this.c = c;
        }
    }

    static class Node {
        int stop;
        long wetTime;
        Node(int stop, long wetTime) {
            this.stop = stop;
            this.wetTime = wetTime;
        }
    }
}

