import java.util.*;

/*
We minimize total "wet time":
- At time 0, Ikacchan starts at stop S and is already in rain.
- While waiting at a stop before boarding a bus, time passes in rain.
- While riding a bus, not wet.
- Upon arrival at G, stop counting immediately.

State:
dp[v][i] = minimum wet time to be at stop v exactly at event time times[v][i].

Transitions:
1) Wait from times[v][i] to times[v][i+1]:
   dp[v][i+1] = min(dp[v][i+1], dp[v][i] + (times[v][i+1] - times[v][i]))
2) Take any bus departing from v at times[v][i]:
   if bus goes to to and arrives at arr, then
   dp[to][idx(arr)] = min(dp[to][idx(arr)], dp[v][i])

Initialization:
At S, before first bus, waiting from time 0 counts as wet time.
So we include time 0 in the compressed times of S and set dp[S][idx(0)] = 0.

Answer:
Minimum dp[G][*], because once arrived at G, no need to wait further.

This is a shortest path on time-expanded DAG processed in increasing time.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Bus {
        int from, to;
        long dep, arr;
        int depIdx, arrIdx;

        Bus(int from, int to, long dep, long arr) {
            this.from = from;
            this.to = to;
            this.dep = dep;
            this.arr = arr;
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int S = fs.nextInt() - 1;
        int G = fs.nextInt() - 1;

        ArrayList<Long>[] timeLists = new ArrayList[N];
        for (int i = 0; i < N; i++) timeLists[i] = new ArrayList<>();

        Bus[] buses = new Bus[M];
        for (int i = 0; i < M; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long t = fs.nextLong();
            long c = fs.nextLong();
            buses[i] = new Bus(u, v, t, t + c);
            timeLists[u].add(t);
            timeLists[v].add(t + c);
        }

        timeLists[S].add(0L);

        long[][] times = new long[N][];
        HashMap<Long, Integer>[] indexMap = new HashMap[N];
        for (int i = 0; i < N; i++) {
            ArrayList<Long> list = timeLists[i];
            Collections.sort(list);
            ArrayList<Long> uniq = new ArrayList<>();
            for (long x : list) {
                if (uniq.isEmpty() || uniq.get(uniq.size() - 1) != x) uniq.add(x);
            }
            times[i] = new long[uniq.size()];
            indexMap[i] = new HashMap<>(uniq.size() * 2 + 1);
            for (int j = 0; j < uniq.size(); j++) {
                times[i][j] = uniq.get(j);
                indexMap[i].put(times[i][j], j);
            }
        }

        ArrayList<Bus>[] departAt = new ArrayList[N];
        for (int i = 0; i < N; i++) departAt[i] = new ArrayList<>();

        for (Bus b : buses) {
            b.depIdx = indexMap[b.from].get(b.dep);
            b.arrIdx = indexMap[b.to].get(b.arr);
            departAt[b.from].add(b);
        }

        // Group buses by departure index for each stop
        ArrayList<Bus>[][] busesByDep = new ArrayList[N][];
        for (int v = 0; v < N; v++) {
            int sz = times[v].length;
            busesByDep[v] = new ArrayList[sz];
            for (int i = 0; i < sz; i++) busesByDep[v][i] = new ArrayList<>();
            for (Bus b : departAt[v]) busesByDep[v][b.depIdx].add(b);
        }

        long[][] dp = new long[N][];
        for (int i = 0; i < N; i++) {
            dp[i] = new long[times[i].length];
            Arrays.fill(dp[i], INF);
        }

        int s0 = indexMap[S].get(0L);
        dp[S][s0] = 0;

        // Process each stop independently in increasing time; bus edges always go to later absolute times.
        // To respect global time order, collect all events and sort by time.
        class Event {
            long time;
            int stop, idx;
            Event(long time, int stop, int idx) {
                this.time = time;
                this.stop = stop;
                this.idx = idx;
            }
        }

        ArrayList<Event> events = new ArrayList<>();
        for (int v = 0; v < N; v++) {
            for (int i = 0; i < times[v].length; i++) {
                events.add(new Event(times[v][i], v, i));
            }
        }
        events.sort(Comparator.comparingLong(e -> e.time));

        for (Event e : events) {
            int v = e.stop;
            int i = e.idx;
            long cur = dp[v][i];
            if (cur == INF) continue;

            // Take buses departing now
            for (Bus b : busesByDep[v][i]) {
                if (cur < dp[b.to][b.arrIdx]) {
                    dp[b.to][b.arrIdx] = cur;
                }
            }

            // Wait until next event time at same stop
            if (i + 1 < times[v].length) {
                long nxt = cur + (times[v][i + 1] - times[v][i]);
                if (nxt < dp[v][i + 1]) {
                    dp[v][i + 1] = nxt;
                }
            }
        }

        long ans = INF;
        for (long x : dp[G]) ans = Math.min(ans, x);

        if (ans == INF) {
            System.out.println(-1);
        } else {
            System.out.println(ans);
        }
    }
}
